# Port of SparkFun_Qwiic_Keypad_Arduino_Library: ask the keypad to load its oldest event (UPDATE_FIFO = 1), then read
# the button register (0 = no event) and the ms since it was pressed.
class QwiicKeypad:
    def __init__(self, i2c, addr=0x4B):
        self.i2c = i2c
        self.addr = addr

    def _read(self, reg):
        self.i2c.writeto(self.addr, bytes([reg]))
        return self.i2c.readfrom(self.addr, 1)[0]

    def update_fifo(self):
        self.i2c.writeto(self.addr, bytes([0x06, 0x01]))

    def button(self):
        return self._read(0x03)

    def time_since_pressed(self):
        msb = self._read(0x04)
        lsb = self._read(0x05)
        return (msb << 8) | lsb

    def version(self):
        return 'v%d.%d' % (self._read(0x01), self._read(0x02))
